#include <stdio.h>

#define MAXD 105
#define MAXEQ 210
#define MAXV 676

static char g[MAXD][MAXD][2];
static long long rowS[MAXD], colS[MAXD];

static int eqVar[MAXEQ][MAXD];
static int eqCnt[MAXEQ][MAXD];
static int eqN[MAXEQ];
static long long eqRem[MAXEQ];
static int eqDeg[MAXEQ];

static int occEq[MAXV][MAXEQ];
static int occCnt[MAXV][MAXEQ];
static int occN[MAXV];

static int isKnown[MAXV];
static long long value[MAXV];
static int visible[MAXV];

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    char tok[32];
    int i, j, t;

    for (i = 0; i < L; i++)
        for (j = 0; j < C; j++) {
            scanf("%31s", tok);
            g[i][j][0] = tok[0];
            g[i][j][1] = tok[1];
        }
    for (i = 0; i < L; i++) scanf("%lld", &rowS[i]);
    for (j = 0; j < C; j++) scanf("%lld", &colS[j]);

    /* row equations: ids 0..L-1 */
    for (i = 0; i < L; i++) {
        int e = i, n = 0;
        for (j = 0; j < C; j++) {
            int cur = (g[i][j][0] - 'a') * 26 + (g[i][j][1] - 'a');
            visible[cur] = 1;
            int f = -1;
            for (t = 0; t < n; t++)
                if (eqVar[e][t] == cur) { f = t; break; }
            if (f >= 0) eqCnt[e][f]++;
            else { eqVar[e][n] = cur; eqCnt[e][n] = 1; n++; }
        }
        eqN[e] = n; eqRem[e] = rowS[i]; eqDeg[e] = n;
        for (t = 0; t < n; t++) {
            int cur = eqVar[e][t];
            occEq[cur][occN[cur]] = e;
            occCnt[cur][occN[cur]] = eqCnt[e][t];
            occN[cur]++;
        }
    }

    /* column equations: ids L..L+C-1 */
    for (j = 0; j < C; j++) {
        int e = L + j, n = 0;
        for (i = 0; i < L; i++) {
            int cur = (g[i][j][0] - 'a') * 26 + (g[i][j][1] - 'a');
            int f = -1;
            for (t = 0; t < n; t++)
                if (eqVar[e][t] == cur) { f = t; break; }
            if (f >= 0) eqCnt[e][f]++;
            else { eqVar[e][n] = cur; eqCnt[e][n] = 1; n++; }
        }
        eqN[e] = n; eqRem[e] = colS[j]; eqDeg[e] = n;
        for (t = 0; t < n; t++) {
            int cur = eqVar[e][t];
            occEq[cur][occN[cur]] = e;
            occCnt[cur][occN[cur]] = eqCnt[e][t];
            occN[cur]++;
        }
    }

    int total = 0, id;
    for (id = 0; id < MAXV; id++)
        if (visible[id]) total++;
    int solved = 0;

    while (solved < total) {
        int progress = 0;
        int e;
        for (e = 0; e < L + C; e++) {
            if (eqDeg[e] != 1) continue;
            int x = -1, k = 0;
            for (t = 0; t < eqN[e]; t++)
                if (!isKnown[eqVar[e][t]]) { x = eqVar[e][t]; k = eqCnt[e][t]; break; }
            if (x < 0) continue;
            long long v = eqRem[e] / k;
            value[x] = v;
            isKnown[x] = 1;
            solved++;
            progress = 1;
            for (t = 0; t < occN[x]; t++) {
                int e2 = occEq[x][t];
                eqRem[e2] -= (long long)occCnt[x][t] * v;
                eqDeg[e2]--;
            }
        }
        if (!progress) break;
    }

    for (id = 0; id < MAXV; id++)
        if (visible[id])
            printf("%c%c %lld\n", 'a' + id / 26, 'a' + id % 26, value[id]);

    return 0;
}
